g=A.b(["ISO 9001:2015 \u2013 \u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u062c\u0648\u062f\u0629","ISO 14001:2015 \u2013 \u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0628\u064a\u0626\u0629","ISO 45001:2018 \u2013 \u0627\u0644\u0635\u062d\u0629 \u0648\u0627\u0644\u0633\u0644\u0627\u0645\u0629 \u0627\u0644\u0645\u0647\u0646\u064a\u0629","\u0645\u0642\u0627\u0648\u0644 \u0645\u0639\u062a\u0645\u062f \u0644\u062f\u0649 \u0623\u0631\u0627\u0645\u0643\u0648 \u0627\u0644\u0633\u0639\u0648\u062f\u064a\u0629","\u0645\u0642\u0627\u0648\u0644 \u0645\u0639\u062a\u0645\u062f \u0644\u062f\u0649 \u0633\u0627\u0628\u0643","\u0645\u0633\u062c\u0644 \u0644\u062f\u0649 \u0647\u064a\u0626\u0629 \u0627\u0644\u0645\u0647\u0646\u062f\u0633\u064a\u0646 \u0627\u0644\u0633\u0639\u0648\u062f\u064a\u064a\u0646"],s)
